"""SQLAlchemy ORM models.

Schema (works on PostgreSQL and SQLite):

* ``phones``          one row per model with typed, query-friendly columns
                      (display size, battery mAh, price, ...) used for
                      rankings, filters and comparisons.
* ``specifications``  every raw spec row scraped from GSMArena
                      (category / name / value), so nothing is lost.
* ``prices``          one row per currency quoted on GSMArena.
* ``benchmarks``      GSMArena lab results (AnTuTu, GeekBench, battery tests...).
* ``reviews``         reviews generated by the multi-agent system.
* ``rag_chunks``      text chunks + embeddings that back semantic retrieval.
"""

from __future__ import annotations

from datetime import date, datetime, timezone

from sqlalchemy import (
    JSON,
    BigInteger,
    Boolean,
    Date,
    DateTime,
    Float,
    ForeignKey,
    Integer,
    LargeBinary,
    String,
    Text,
    UniqueConstraint,
)
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column, relationship


def _utcnow() -> datetime:
    return datetime.now(timezone.utc)


class Base(DeclarativeBase):
    pass


class Phone(Base):
    __tablename__ = "phones"

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    name: Mapped[str] = mapped_column(String(120), unique=True, index=True)
    brand: Mapped[str] = mapped_column(String(40), default="Samsung")
    gsmarena_id: Mapped[int | None] = mapped_column(Integer)
    url: Mapped[str] = mapped_column(String(300))
    image_url: Mapped[str | None] = mapped_column(String(300))
    popularity_hits: Mapped[int | None] = mapped_column(BigInteger)
    fans: Mapped[int | None] = mapped_column(Integer)

    # Launch
    announced: Mapped[str | None] = mapped_column(String(120))
    announced_date: Mapped[date | None] = mapped_column(Date)
    status: Mapped[str | None] = mapped_column(String(200))
    release_date: Mapped[date | None] = mapped_column(Date)

    # Body
    dimensions: Mapped[str | None] = mapped_column(Text)
    thickness_mm: Mapped[float | None] = mapped_column(Float)
    weight_g: Mapped[float | None] = mapped_column(Float)
    build: Mapped[str | None] = mapped_column(Text)
    ip_rating: Mapped[str | None] = mapped_column(String(10))

    # Display
    display_type: Mapped[str | None] = mapped_column(Text)
    display_size_in: Mapped[float | None] = mapped_column(Float)
    display_resolution: Mapped[str | None] = mapped_column(Text)
    resolution_width: Mapped[int | None] = mapped_column(Integer)
    resolution_height: Mapped[int | None] = mapped_column(Integer)
    ppi: Mapped[int | None] = mapped_column(Integer)
    refresh_rate_hz: Mapped[int | None] = mapped_column(Integer)
    peak_brightness_nits: Mapped[int | None] = mapped_column(Integer)
    display_protection: Mapped[str | None] = mapped_column(Text)

    # Platform & memory
    os: Mapped[str | None] = mapped_column(Text)
    chipset: Mapped[str | None] = mapped_column(Text)
    cpu: Mapped[str | None] = mapped_column(Text)
    gpu: Mapped[str | None] = mapped_column(Text)
    card_slot: Mapped[str | None] = mapped_column(String(120))
    memory_options: Mapped[str | None] = mapped_column(Text)
    ram_gb: Mapped[float | None] = mapped_column(Float)
    storage_gb_max: Mapped[int | None] = mapped_column(Integer)

    # Cameras
    main_camera_setup: Mapped[str | None] = mapped_column(String(40))
    main_camera_mp: Mapped[float | None] = mapped_column(Float)
    main_camera_count: Mapped[int | None] = mapped_column(Integer)
    max_optical_zoom: Mapped[float | None] = mapped_column(Float)
    main_camera_video: Mapped[str | None] = mapped_column(String(120))
    selfie_camera_mp: Mapped[float | None] = mapped_column(Float)
    selfie_camera_video: Mapped[str | None] = mapped_column(String(120))

    # Battery
    battery_mah: Mapped[int | None] = mapped_column(Integer)
    battery_type: Mapped[str | None] = mapped_column(String(40))
    charging: Mapped[str | None] = mapped_column(Text)
    charging_wired_w: Mapped[float | None] = mapped_column(Float)
    charging_wireless_w: Mapped[float | None] = mapped_column(Float)

    # Misc
    colors: Mapped[str | None] = mapped_column(Text)
    price_text: Mapped[str | None] = mapped_column(Text)
    price_usd: Mapped[float | None] = mapped_column(Float)

    scraped_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=_utcnow)

    specs: Mapped[list["Specification"]] = relationship(
        back_populates="phone", cascade="all, delete-orphan", order_by="Specification.position"
    )
    prices: Mapped[list["Price"]] = relationship(back_populates="phone", cascade="all, delete-orphan")
    benchmarks: Mapped[list["Benchmark"]] = relationship(back_populates="phone", cascade="all, delete-orphan")
    reviews: Mapped[list["Review"]] = relationship(back_populates="phone", cascade="all, delete-orphan")
    chunks: Mapped[list["RagChunk"]] = relationship(back_populates="phone", cascade="all, delete-orphan")

    @property
    def short_name(self) -> str:
        return self.name.replace("Samsung ", "", 1)

    def __repr__(self) -> str:  # pragma: no cover - debugging aid
        return f"<Phone {self.name!r}>"


class Specification(Base):
    __tablename__ = "specifications"

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    phone_id: Mapped[int] = mapped_column(ForeignKey("phones.id", ondelete="CASCADE"), index=True)
    category: Mapped[str] = mapped_column(String(60), index=True)
    name: Mapped[str] = mapped_column(String(80))
    spec_key: Mapped[str | None] = mapped_column(String(60))
    value: Mapped[str] = mapped_column(Text)
    position: Mapped[int] = mapped_column(Integer, default=0)

    phone: Mapped[Phone] = relationship(back_populates="specs")


class Price(Base):
    __tablename__ = "prices"
    __table_args__ = (UniqueConstraint("phone_id", "currency", name="uq_price_phone_currency"),)

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    phone_id: Mapped[int] = mapped_column(ForeignKey("phones.id", ondelete="CASCADE"), index=True)
    currency: Mapped[str] = mapped_column(String(3))
    amount: Mapped[float] = mapped_column(Float)
    raw: Mapped[str | None] = mapped_column(Text)
    source: Mapped[str] = mapped_column(String(40), default="GSMArena")

    phone: Mapped[Phone] = relationship(back_populates="prices")


class Benchmark(Base):
    __tablename__ = "benchmarks"

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    phone_id: Mapped[int] = mapped_column(ForeignKey("phones.id", ondelete="CASCADE"), index=True)
    test: Mapped[str] = mapped_column(String(60), index=True)
    version: Mapped[str | None] = mapped_column(String(60))
    score: Mapped[float] = mapped_column(Float)
    unit: Mapped[str] = mapped_column(String(20))
    raw: Mapped[str | None] = mapped_column(Text)

    phone: Mapped[Phone] = relationship(back_populates="benchmarks")


class Review(Base):
    __tablename__ = "reviews"

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    phone_id: Mapped[int] = mapped_column(ForeignKey("phones.id", ondelete="CASCADE"), index=True)
    content: Mapped[str] = mapped_column(Text)
    scores: Mapped[dict] = mapped_column(JSON, default=dict)
    pros: Mapped[list] = mapped_column(JSON, default=list)
    cons: Mapped[list] = mapped_column(JSON, default=list)
    generator: Mapped[str] = mapped_column(String(120))
    verified: Mapped[bool] = mapped_column(Boolean, default=False)
    verification: Mapped[dict] = mapped_column(JSON, default=dict)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=_utcnow)

    phone: Mapped[Phone] = relationship(back_populates="reviews")


class RagChunk(Base):
    __tablename__ = "rag_chunks"

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    phone_id: Mapped[int] = mapped_column(ForeignKey("phones.id", ondelete="CASCADE"), index=True)
    category: Mapped[str] = mapped_column(String(60))
    content: Mapped[str] = mapped_column(Text)
    embedding: Mapped[bytes] = mapped_column(LargeBinary)
    embedding_model: Mapped[str] = mapped_column(String(120))

    phone: Mapped[Phone] = relationship(back_populates="chunks")
